mapper.select:
select SCHEME_ID as schemeId, SCHEME_NAME as schemeName, SCHEME_DESCRIPTION as schemeDescription, ISDEFAULT as isdefault, CREATE_USER as createUser, CREATE_DEPT as createDept, CREATE_TIME as createTime, UPDATE_USER as updateUser, UPDATE_TIME as updateTime from bok_VAL_SCHEME
AND (SCHEME_ID like '%' || #{searchKey} || '%' OR SCHEME_NAME like '%' || #{searchKey} || '%')
AND (SCHEME_ID like '%' || #{search} || '%' OR SCHEME_NAME like '%' || #{search} || '%')
AND (SCHEME_ID = #{schemeId} OR SCHEME_NAME = #{schemeName} )
AND SCHEME_NAME = #{schemeName}
AND SCHEME_ID != #{owner}

select sd.SCHEME_DETAIL_ID as schemeDetailId, /** 方案明细代码 **/ sd.SCHEME_ID as schemeId,/** 方案代码 **/ sd.TRADE_MARKET as tradeMarketCode,/** 交易市场Code **/ sd.TRADE_MARKET as tradeMarket,/** 交易市场 **/ sd.SEC_TYPE as secTypeCode,/** 证券品种Code **/ sd.SEC_TYPE as secType,/** 证券品种 **/ sd.SEC_DETAIL_TYPE as secDetailTypeCode,/** 证券细分类Code **/ sd.SEC_DETAIL_TYPE as secDetailType,/** 证券细分类 **/ sd.INV_AIM as invAimCode,/** 投资目的Code **/ sd.INV_AIM as invAim,/** 投资目的 **/ sd.VALUATION_METHOD as valuationMethodCode,/** 估值方法Code **/ sd.VALUATION_METHOD as valuationMethod,/** 估值方法 **/ /**add by yinya on 20220427 **/ sd.VALUATION_ID as valuationId ,/** 估值模型 **/ /**add by yinya on 20220427 **/ sd.VALUATION_PRICE as valuationPriceCode,/** 估值市价Code **/ sd.VALUATION_PRICE as valuationPrice,/** 估值市价 **/ sd.VALUATION_PRICE_2 as valuationPrice2Code,/** 估值第二市价Code **/ sd.VALUATION_PRICE_2 as valuationPrice2,/** 估值第二市价 **/ sd.QUOTA_DIGIT as quotaDigit,/** 行情位数 **/ sd.PRICE_TAIL_MODE as priceTailMode, /** 行情尾数处理方式 **/ sd.PRICE_TAIL_MODE as priceTailModeCode, /** 行情尾数处理方式 **/ sd.PRICE_CLASS as priceClass, /** 价格类型 **/ sd.PRICE_CLASS as priceClassCode, /** 价格类型 **/ sd.VALUATION_DATE as valuationDate, /** 估值日期 **/ sd.VALUATION_DATE as valuationDateCode, TO_CHAR(sd.VDATE,'YYYY-MM-DD') AS vdate,/** 开始日 **/ TO_CHAR(sd.MDATE,'YYYY-MM-DD') AS mdate,/** 结束日 **/
s.SCHEME_DESCRIPTION as schemeDescription from bok_VAL_SCHEME_DETAIL sd inner join bok_VAL_SCHEME s on sd.SCHEME_ID = s.SCHEME_ID
AND sd.SCHEME_ID = #{schemeId}
AND sd.SEC_TYPE in
#{item}
AND sd.TRADE_MARKET in
#{item}
AND sd.SEC_DETAIL_TYPE in
#{item}
AND sd.INV_AIM in
#{item}
AND sd.SCHEME_DETAIL_ID != #{owner}
AND sd.VDATE = TO_DATE(#{vdate},'YYYY-MM-DD')
AND (sd.SCHEME_DETAIL_ID in
null) OR sd.SCHEME_DETAIL_ID in (
#{item}
)
order by sd.update_time desc

select t.SCHEME_DETAIL_ID as schemeDetailId, /** 方案明细代码 **/ t.SCHEME_ID as schemeId,/** 方案代码 **/ nvl(vfp.finprod_market_id,t.FINPROD_ID) as finprodId,/** 资产代码 数据库中存资产代码，页面显示市场代码 **/ t.FINPROD_NAME as finprodName,/** 资产名称 **/ t.TRADE_MARKET as tradeMarketCode,/** 交易市场Code **/ t.TRADE_MARKET as tradeMarket,/** 交易市场 **/ t.SEC_TYPE as secTypeCode,/** 证券品种Code **/ t.SEC_TYPE as secType,/** 证券品种 **/ t.SEC_DETAIL_TYPE as secDetailTypeCode,/** 证券细分类Code **/ t.SEC_DETAIL_TYPE as secDetailType,/** 证券细分类 **/ t.INV_AIM as invAimCode,/** 投资目的Code **/ t.INV_AIM as invAim,/** 投资目的 **/ t.VALUATION_METHOD as valuationMethodCode,/** 估值方法Code **/ t.VALUATION_METHOD as valuationMethod,/** 估值方法 **/ t.VALUATION_PRICE as valuationPriceCode,/** 估值市价Code **/ t.VALUATION_PRICE as valuationPrice,/** 估值市价 **/ t.VALUATION_PRICE_2 as valuationPrice2Code,/** 估值第二市价Code **/ t.VALUATION_PRICE_2 as valuationPrice2,/** 估值第二市价 **/ t.QUOTA_DIGIT as quotaDigit,/** 行情位数 **/ t.PRICE_TAIL_MODE as priceTailMode, /** 行情尾数处理方式 **/ t.PRICE_TAIL_MODE as priceTailModeCode, /** 行情尾数处理方式 **/ t.PRICE_CLASS as priceClass, /** 价格类型 **/ t.PRICE_CLASS as priceClassCode, /** 价格类型 **/ t.VALUATION_DATE as valuationDate, /** 估值日期 **/ t.VALUATION_DATE as valuationDateCode, TO_CHAR(t.VDATE,'YYYY-MM-DD') AS vdate,/** 开始日 **/ TO_CHAR(t.MDATE,'YYYY-MM-DD') AS mdate,/** 结束日 **/ vfp.finprod_type as finprodType from BOK_VAL_SCHEME_DETAIL_SPECIAL t left join FIN_PRODUCT vfp on t.FINPROD_ID = vfp.FINPROD_ID and (vfp.FINPROD_TYPE = 'F01' or ((vfp.profit_type is null or vfp.profit_type = '02') and vfp.finprod_type = 'F17' ))
AND t.SCHEME_ID = #{schemeId}
AND (t.FINPROD_ID like '%' || #{search} || '%' OR t.FINPROD_NAME like '%' || #{search} || '%' )
AND nvl(t.FINPROD_ID,vfp.finprod_market_id) in
#{item}
AND t.TRADE_MARKET in
#{item}
AND t.INV_AIM in
#{item}
AND t.SCHEME_DETAIL_ID != #{owner}
AND t.VDATE is not null AND t.MDATE is null
AND t.MDATE >= TO_DATE(#{vdate},'YYYY-MM-DD')
AND t.VDATE <= TO_DATE(#{mdate},'YYYY-MM-DD') AND t.MDATE is null
AND not(t.VDATE > TO_DATE(#{mdate}, 'YYYY-MM-DD') OR t.MDATE < TO_DATE(#{vdate}, 'YYYY-MM-DD'))
AND t.SCHEME_DETAIL_ID in
#{item}
order by t.update_time desc

select distinct FINPROD_ID as finprodId,/** 资产代码 **/ FINPROD_NAME as finprodName/** 资产名称 **/ from BOK_VAL_SCHEME_DETAIL_SPECIAL
AND SCHEME_ID = #{schemeId}
AND (FINPROD_ID like '%' || #{search} || '%' OR FINPROD_NAME like '%' || #{search} || '%' )

select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like '%' || #{search} || '%'
order by sdl.ITEM_CODE

select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like '%' || #{search} || '%'
order by sdl.ITEM_CODE
